def date_di_creazione(apps, schema_editor):
    """Per le opportunità di prima: la data del primo messaggio nel loro registro (la creazione), se c'è."""
    Opportunita = apps.get_model("crm", "Opportunita")
    Messaggio = apps.get_model("core", "Messaggio")
    ContentType = apps.get_model("contenttypes", "ContentType")
    tipo = ContentType.objects.filter(app_label="crm", model="opportunita").first()
    if tipo is None:
        return
    primi = {}
    for oid, quando in Messaggio.objects.filter(content_type=tipo).order_by("creato").values_list("object_id", "creato"):
        primi.setdefault(oid, quando)
    for o in Opportunita.objects.all().only("pk", "creata_il", "chiusa_il"):
        quando = primi.get(o.pk)
        data = quando.date() if quando else (o.chiusa_il or o.creata_il)
        if data != o.creata_il:
            Opportunita.objects.filter(pk=o.pk).update(creata_il=data)


